  return `<div class="inbox-grid">${conversationList()}<section class="chat"><header class="chat-header"><div class="identity">${avatar(c)}<div><h2>${esc(c.name)}</h2><span class="muted">Instagram · @${esc(c.handle)}</span></div></div>${badge(conv.mode)}</header><div class="ownership-bar"><span>${conv.mode === 'human' ? 'You own this conversation. The assistant is paused.' : conv.mode === 'awaiting_human' ? 'Waiting for a person. Automatic replies are paused.' : conv.mode === 'paused' ? 'Conversation paused.' : conv.mode === 'review' ? 'Assistant drafts require your approval.' : 'Assistant replies automatically inside the reply window.'}</span>${!c.doNotContact ? ['auto','review','awaiting_human','paused'].includes(conv.mode) ? btn('Take over','mode',c.id,'mini secondary','data-mode="human"') : btn('Return to assistant','mode',c.id,'mini secondary','data-mode="auto"') : badge('opted out','red')}</div><div class="messages">${messagesFor(c.id).map(messageHtml).join('') || empty('No conversation yet','Prepare a first hello from the Prospects view.')}</div><div class="composer-area">${state.demo ? `<details class="demo-tools"><summary>Try a customer message <span>DEMO</span></summary><div class="quick-actions">${[['Project details','We are planning a home in Bellevue, 2400 sqft, 4 bedrooms and 3 bathrooms. Budget is $900k. Permit not started.'],['Show references','Can you show me a project example?'],['Book a meeting','I would like to book a meeting'],['Ask the price','How much will this project cost?'],['Ask a person','Can I talk to a human?'],['Opt out','Please stop contacting me']].map(([label,text]) => btn(label,'simulate',c.id,'chip',`data-text="${esc(text)}"`)).join('')}${slots.length && Date.parse(conv.slotsExpireAt) > Date.now() ? slots.map((s,i) => btn(`Choose ${String.fromCharCode(65+i)} · ${date(s.start)}`,'simulate',c.id,'chip',`data-text="${String.fromCharCode(65+i)}"`)).join('') : ''}</div></details>` : ''}${!c.doNotContact ? `<form data-form="message" data-id="${c.id}" class="message-form"><label class="composer-label">${state.demo ? '<select name="direction" aria-label="Message role"><option value="inbound">Simulate customer DM</option value="human" '+(conv.mode !== 'human' ? 'disabled' : '')+'>Send as intake team</option></select>' : 'Reply as intake team'}</label><textarea name="text" rows="2" placeholder="${state.demo ? 'Type what the customer says…' : 'Write your reply…'}" required maxlength="4000"></textarea><div class="composer-footer"><small>${state.demo ? 'Inbound demo messages are processed by the agent.' : 'Your text is sent to Instagram. Assistant ownership stays unchanged.'}</small><button class="button primary" type="submit">${state.demo ? 'Process message ↗' : 'Send reply ↗'}</button></div></form>` : `<p class="muted">${conv.mode === 'auto' ? 'Waiting for customer messages from Instagram.' : 'Take over to reply as the team.'}</p>`}</div></section><aside class="customer-panel">${customerDetails(c)}</aside></div>`;
